param(
  [Parameter(Mandatory=$true)][string]$Executable,
  [Parameter(Mandatory=$true)][string]$SourceRoot,
  [string]$OutputDirectory,
  [ValidateSet('normal','gbv')][string]$Mode='normal',
  [ValidateSet(2,4)][int]$CascadeCount=4,
  [string]$PerformanceReceipt
)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
function Full([string]$Path){[IO.Path]::GetFullPath($Path)}
function Sha([string]$Path){$algorithm=[Security.Cryptography.SHA256]::Create();$stream=[IO.File]::OpenRead($Path);try{([BitConverter]::ToString($algorithm.ComputeHash($stream))-replace'-','').ToLowerInvariant()}finally{$stream.Dispose();$algorithm.Dispose()}}
function TextSha([string]$Text){$algorithm=[Security.Cryptography.SHA256]::Create();try{([BitConverter]::ToString($algorithm.ComputeHash([Text.Encoding]::UTF8.GetBytes($Text)))-replace'-','').ToLowerInvariant()}finally{$algorithm.Dispose()}}
function SourceSnapshot([string]$Root){$paths=@(& git -C $Root diff --name-only --diff-filter=ACMRTUXB --);if($LASTEXITCODE){throw'git diff failed'};$files=@($paths|Where-Object{$_}|Sort-Object -CaseSensitive|ForEach-Object{$path=$_.Replace('\','/');$full=Full(Join-Path $Root $_);[ordered]@{path=$path;sha256=Sha $full}});$canonical=($files|ForEach-Object{"$($_.path):$($_.sha256)`n"})-join'';[ordered]@{digest=TextSha $canonical;files=$files}}
function Measure-Contact([string]$Disabled,[string]$Enabled){$off=[Drawing.Bitmap]::FromFile($Disabled);$on=[Drawing.Bitmap]::FromFile($Enabled);try{[long]$changed=0;$darkened=0;$brightened=0;for($y=100;$y-lt620;$y+=2){for($x=0;$x-lt1280;$x+=2){$a=$off.GetPixel($x,$y);$b=$on.GetPixel($x,$y);$before=$a.R+$a.G+$a.B;$after=$b.R+$b.G+$b.B;if([Math]::Abs($before-$after)-gt3){$changed++};if($after+6-lt$before){$darkened++};if($after-gt$before+12){$brightened++}}};[ordered]@{changed=$changed;darkened=$darkened;brightened=$brightened}}finally{$off.Dispose();$on.Dispose()}}
$exe=Full $Executable;$root=Full $SourceRoot;if(!(Test-Path -LiteralPath $exe -PathType Leaf)){throw'EngineLab executable missing'};if(!(Test-Path -LiteralPath $root -PathType Container)){throw'source root missing'}
if(!$OutputDirectory){$OutputDirectory=Join-Path ([IO.Path]::GetTempPath()) ("Aevrynd-EngineLab-shadow-{0}"-f[Guid]::NewGuid().ToString('D'))};$out=Full $OutputDirectory;if(Test-Path -LiteralPath $out){throw'immutable output already exists'};New-Item -ItemType Directory -Path $out|Out-Null
$cwd=Full(Get-Location).Path;$exeBefore=Sha $exe;$treeBefore=SourceSnapshot $root;$mainSource=Full(Join-Path $root 'games/engine_lab/native/src/EngineLabGame.cpp');$gameManifest=Full(Join-Path $root 'games/engine_lab/game.json');$runnerSource=Full $PSCommandPath;$mainBefore=Sha $mainSource;$manifestBefore=Sha $gameManifest;$runnerBefore=Sha $runnerSource;$savedValidation=[Environment]::GetEnvironmentVariable('AEVRYND_GPU_VALIDATION','Process');$savedDirectory=[Environment]::GetEnvironmentVariable('AEVRYND_ENGINE_LAB_SHADOW_CAPTURE_DIRECTORY','Process');$savedCascades=[Environment]::GetEnvironmentVariable('AEVRYND_ENGINE_LAB_SHADOW_CASCADES','Process')
try{[Environment]::SetEnvironmentVariable('AEVRYND_GPU_VALIDATION',$(if($Mode-ceq'gbv'){'1'}else{$null}),'Process');[Environment]::SetEnvironmentVariable('AEVRYND_ENGINE_LAB_SHADOW_CAPTURE_DIRECTORY',$out,'Process');[Environment]::SetEnvironmentVariable('AEVRYND_ENGINE_LAB_SHADOW_CASCADES',[string]$CascadeCount,'Process');$process=Start-Process -FilePath $exe -ArgumentList '--capture-shadow-demo' -WorkingDirectory $cwd -WindowStyle Hidden -Wait -PassThru}finally{[Environment]::SetEnvironmentVariable('AEVRYND_GPU_VALIDATION',$savedValidation,'Process');[Environment]::SetEnvironmentVariable('AEVRYND_ENGINE_LAB_SHADOW_CAPTURE_DIRECTORY',$savedDirectory,'Process');[Environment]::SetEnvironmentVariable('AEVRYND_ENGINE_LAB_SHADOW_CASCADES',$savedCascades,'Process')}
if($process.ExitCode){throw "EngineLab shadow capture exit=$($process.ExitCode)"};$exeAfter=Sha $exe;$treeAfter=SourceSnapshot $root;$mainAfter=Sha $mainSource;$manifestAfter=Sha $gameManifest;$runnerAfter=Sha $runnerSource;if($exeBefore-cne$exeAfter-or$treeBefore.digest-cne$treeAfter.digest-or$mainBefore-cne$mainAfter-or$manifestBefore-cne$manifestAfter-or$runnerBefore-cne$runnerAfter){throw 'inputs changed during capture'}
$runtimePath=Join-Path $out 'shadow-demo-runtime-receipt.json';if(!(Test-Path -LiteralPath $runtimePath -PathType Leaf)){throw'runtime receipt missing'};$runtime=Get-Content -Raw -LiteralPath $runtimePath|ConvertFrom-Json;$expectedBytes=[long]$CascadeCount*2048*2048*4;$expectedMask=1-shl($CascadeCount-1);if($runtime.runId-notmatch'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'-or$runtime.phase-ne'shadow-v255'-or$runtime.cascadeConfigured-ne$CascadeCount-or$runtime.cascadeCount-ne$CascadeCount-or$runtime.cascadeResolution-ne2048-or$runtime.shadowBytes-ne$expectedBytes-or$runtime.farCascadeMask-ne$expectedMask-or$runtime.farCascadeInstances-lt1-or$runtime.manualMasks-lt1-or$runtime.contactRequested-ne1-or$runtime.contactExecuted-ne1-or$runtime.contactEvaluationPasses-lt1-or$runtime.effective-ne1-or$runtime.gpuFrameNanoseconds-lt1){throw'runtime shadow gate failed'}
$splits=@($runtime.cascadeSplits);if($splits.Count-ne4-or$splits[0]-le0-or$splits[1]-le$splits[0]-or($CascadeCount-eq4-and($splits[2]-le$splits[1]-or$splits[3]-le$splits[2]))){throw'cascade split gate failed'};if((@($runtime.cascadeRendered)|Measure-Object -Sum).Sum-lt$CascadeCount-or(@($runtime.cascadeReused)|Measure-Object -Sum).Sum-lt1){throw'cascade render/cache gate failed'}
if($Mode-ceq'gbv'){if($runtime.gpuValidationRequested-ne1-or$runtime.gpuValidationAvailable-ne1-or$runtime.gpuValidationExecuted-ne1-or$runtime.debugLayerEnabled-ne1-or$runtime.gpuValidationPassed-ne1-or$runtime.gpuValidationErrors-ne0-or$runtime.gpuValidationWarnings-ne0){throw'GBV gate failed'}}elseif($runtime.gpuValidationRequested-ne0-or$runtime.gpuValidationAvailable-ne0-or$runtime.gpuValidationExecuted-ne0-or$runtime.debugLayerEnabled-ne0-or$runtime.gpuValidationPassed-ne0-or$runtime.gpuValidationErrors-ne0-or$runtime.gpuValidationWarnings-ne0){throw'normal validation gate failed'}
Add-Type -AssemblyName System.Drawing;$names=@('contact-shadow-disabled.png','contact-shadow-enabled.png','far-cascade-receiver.png','day-shadow.png','dusk-shadow.png','night-shadow.png');$captures=@();foreach($name in $names){$path=Join-Path $out $name;if(!(Test-Path -LiteralPath $path -PathType Leaf)){throw"missing $name"};$bitmap=[Drawing.Bitmap]::FromFile($path);try{if($bitmap.Width-ne1280-or$bitmap.Height-ne720){throw"dimensions $name"};$captures+=[ordered]@{file=$name;width=$bitmap.Width;height=$bitmap.Height;sha256=Sha $path}}finally{$bitmap.Dispose()}};if(($captures.sha256|Sort-Object -Unique).Count-ne6){throw'capture hashes were not unique'}
$contact=Measure-Contact (Join-Path $out 'contact-shadow-disabled.png') (Join-Path $out 'contact-shadow-enabled.png');if($contact.changed-lt64-or$contact.darkened-lt32-or$contact.brightened-gt[Math]::Max(16,[int]($contact.darkened*.35))){throw 'contact A/B semantic gate failed'}
$performance=[ordered]@{receipt='';fourCascadeRegression=$null;maximumRegression=.05;passed=$false};if($PerformanceReceipt){$performancePath=Full $PerformanceReceipt;$benchmark=Get-Content -Raw -LiteralPath $performancePath|ConvertFrom-Json;$regression=[double]$benchmark.performance.fourCascadeRegression;if($regression-gt.05){throw'four-cascade performance regression exceeded 5%'};$performance=[ordered]@{receipt=$performancePath;sha256=Sha $performancePath;fourCascadeRegression=$regression;maximumRegression=.05;passed=$true}}
$receipt=[ordered]@{schemaVersion=1;runId=$runtime.runId;mode=$Mode;cascadeCount=$CascadeCount;source=[ordered]@{root=$root;workingTreeDigestBefore=$treeBefore.digest;workingTreeDigestAfter=$treeAfter.digest;trackedWipFiles=$treeBefore.files;engineLabSource=[ordered]@{path=$mainSource;sha256Before=$mainBefore;sha256After=$mainAfter};gameManifest=[ordered]@{path=$gameManifest;sha256Before=$manifestBefore;sha256After=$manifestAfter};runner=[ordered]@{path=$runnerSource;sha256Before=$runnerBefore;sha256After=$runnerAfter}};executable=[ordered]@{path=$exe;sha256Before=$exeBefore;sha256After=$exeAfter};command=[ordered]@{file=$exe;arguments=@('--capture-shadow-demo');workingDirectory=$cwd;captureDirectory=$out;gpuValidation=$(if($Mode-ceq'gbv'){'1'}else{''});configuredCascades=$CascadeCount};process=[ordered]@{exitCode=[int]$process.ExitCode};dimensions=[ordered]@{width=1280;height=720};captures=$captures;semantics=[ordered]@{contact=$contact;farCascade=[ordered]@{mask=[int]$runtime.farCascadeMask;instances=[int]$runtime.farCascadeInstances}};runtime=$runtime;performance=$performance;gpuValidation=[ordered]@{requested=[int]$runtime.gpuValidationRequested;available=[int]$runtime.gpuValidationAvailable;executed=[int]$runtime.gpuValidationExecuted;debug=[int]$runtime.debugLayerEnabled;passed=[int]$runtime.gpuValidationPassed;errors=[int]$runtime.gpuValidationErrors;warnings=[int]$runtime.gpuValidationWarnings}}
$receipt|ConvertTo-Json -Depth 12|Set-Content -LiteralPath (Join-Path $out 'shadow-demo-capture-receipt.json') -Encoding UTF8;Write-Output "ENGINE_LAB_SHADOW_CAPTURE_PASS mode=$Mode cascades=$CascadeCount runId=$($runtime.runId) output=$out"
